  ('13e66d53-54b9-5467-a5e7-9792b1df485b'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Le code de Nour","competence":"resoudre","situation":"Nour code deux nombres (x ; y) avec la matrice M : le système 3x + 2y = 7 et 4x + 3y = 10 s’écrit M X = B, avec X la colonne (x ; y) et B la colonne (7 ; 10). Elle veut inverser M.","documents":[{"id":"m","type":"tableau","titre":"La matrice M","colonnes":["Colonne 1","Colonne 2"],"lignes":[[3,2],[4,3]],"enteteLignes":false,"source":"M a deux lignes et deux colonnes"},{"id":"i","type":"texte","genre":"consigne","titre":"Inverse d’une matrice 2 × 2","blocs":["Pour une matrice de coefficients a, b (première ligne) et c, d (seconde ligne), le déterminant vaut ad − bc.","Si ce déterminant est non nul, l’inverse s’obtient en échangeant a et d, en changeant le signe de b et de c, puis en divisant par le déterminant."]}],"questions":[{"enonce":"Quel est le déterminant de M ? Calcule 3 × 3 − 2 × 4.","aide":"a = 3, b = 2, c = 4, d = 3.","type":"nombre"},{"enonce":"Touche le coefficient de M qui devient −4 dans l’inverse.","aide":"Dans l’inverse, b et c changent de signe : c est le coefficient de la seconde ligne, première colonne.","type":"zone","document":"m","multiple":false},{"enonce":"Quelle est la première ligne de l’inverse, à gauche ? Donne son premier coefficient (le déterminant vaut 1).","aide":"Le premier coefficient est d.","type":"nombre"},{"enonce":"Calcule x dans X = M⁻¹ B, avec B = (7 ; 10). On a x = 3 × 7 + (−2) × 10.","aide":"3 × 7 = 21 et 2 × 10 = 20.","type":"nombre"},{"enonce":"Calcule y avec y = (−4) × 7 + 3 × 10.","aide":"−28 + 30.","type":"nombre"}]}$ex$::jsonb,
