  ('13e66d53-54b9-5467-a5e7-9792b1df485b'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Une puissance sans multiplier cent fois","competence":"calculer","situation":"La matrice A est fournie sous la forme A = P D P⁻¹, avec D diagonale. Grâce à cette écriture, Aⁿ = P Dⁿ P⁻¹ : on n’a pas besoin de multiplier A par elle-même n fois.","documents":[{"id":"p","type":"tableau","titre":"Les matrices fournies","colonnes":["Matrice","Première ligne","Seconde ligne"],"lignes":[["P","1 ; 1","1 ; 2"],["D","1 ; 0","0 ; 3"],["P⁻¹","2 ; −1","−1 ; 1"]],"enteteLignes":true,"source":"P × P⁻¹ = I : on peut le vérifier"},{"id":"c","type":"texte","genre":"consigne","titre":"Consigne","blocs":["Dⁿ s’obtient en élevant chaque coefficient diagonal de D à la puissance n.","Coefficient (i ; j) : ligne i, colonne j."]}],"questions":[{"enonce":"Quel est le second coefficient diagonal de D⁴ ?","aide":"Élève 3 à la puissance 4.","type":"nombre"},{"enonce":"Calcule le coefficient (1 ; 1) de A². On a P D² = lignes (1 ; 9) et (1 ; 18) : multiplie la première ligne par la première colonne de P⁻¹.","aide":"Première ligne (1 ; 9) fois première colonne (2 ; −1) : 1 × 2 + 9 × (−1).","type":"nombre"},{"enonce":"Pourquoi calculer Aⁿ avec P Dⁿ P⁻¹ est-il bien plus rapide qu’en multipliant n fois ?","aide":"Regarde ce que vaut Dⁿ quand D est diagonale.","type":"choix","options":[{"id":"a","texte":"Parce que Dⁿ s’obtient en élevant seulement deux nombres à la puissance n"},{"id":"b","texte":"Parce que A est égale à D, ce qui évite de multiplier les matrices entre elles"},{"id":"c","texte":"Parce que le produit matriciel devient commutatif dès que l’on utilise une matrice D"},{"id":"d","texte":"Parce que P et P⁻¹ disparaissent du calcul, ce qui laisse uniquement la matrice D"}],"multiple":false},{"enonce":"Calcule le coefficient (2 ; 2) de A³. On a P D³ = lignes (1 ; 27) et (1 ; 54).","aide":"Seconde ligne (1 ; 54) fois seconde colonne (−1 ; 1) : 1 × (−1) + 54 × 1.","type":"nombre"},{"enonce":"Calcule le coefficient (1 ; 2) de A⁴. On a P D⁴ = lignes (1 ; 81) et (1 ; 162).","aide":"Première ligne (1 ; 81) fois seconde colonne (−1 ; 1) : −1 + 81.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":81,"tolerance":0},"affichage":"81","explication":"3⁴ = **81** (le premier coefficient reste 1⁴ = 1)."},{"cle":{"type":"nombre","valeur":-7,"tolerance":0},"affichage":"−7","explication":"1 × 2 + 9 × (−1) = **−7**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Dans P D P⁻¹ P D P⁻¹ …, les P⁻¹ P se simplifient : Aⁿ = P Dⁿ P⁻¹, et **Dⁿ se calcule coefficient par coefficient**."},{"cle":{"type":"nombre","valeur":53,"tolerance":0},"affichage":"53","explication":"−1 + 54 = **53**."},{"cle":{"type":"nombre","valeur":80,"tolerance":0},"affichage":"80","explication":"−1 + 81 = **80**."}]$ex$::jsonb),
