  ('60bd8e40-bffc-568b-8e6d-1b2016be63d3'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Un quotient et une équation","competence":"calculer","situation":"Jade veut écrire (2 + 3i) / (1 − i) sous forme algébrique, en multipliant haut et bas par le conjugué du dénominateur. Elle résout aussi une équation d’inconnue z = a + ib.","documents":[{"id":"q","type":"tableau","titre":"Calcul du quotient","colonnes":["Étape","Résultat"],"lignes":[["Numérateur : (2 + 3i)(1 + i)","−1 + 5i"],["Dénominateur : (1 − i)(1 + i)","2"],["Quotient","?"]],"enteteLignes":true,"source":"Méthode du conjugué"},{"id":"e","type":"texte","genre":"consigne","titre":"Équation","blocs":["Trouver le nombre complexe z = a + ib tel que z + 2 z̄ = 9 + 4i.","Indice : z + 2 z̄ = 3a − ib."]}],"questions":[{"enonce":"Touche le résultat qui est un nombre réel.","aide":"Un nombre réel n’a pas de partie imaginaire.","type":"zone","document":"q","multiple":false},{"enonce":"Quelle est la partie réelle du quotient ? Divise −1 par 2.","aide":"Divise la partie réelle du numérateur par le dénominateur.","type":"nombre"},{"enonce":"Quelle est la partie imaginaire du quotient ?","aide":"Divise 5 par 2.","type":"nombre"},{"enonce":"Pour 3a − ib = 9 + 4i, quelle est la valeur de a ? Identifie les parties réelles.","aide":"3a = 9.","type":"nombre"},{"enonce":"Quelle est la valeur de b ? Identifie les parties imaginaires : −b = 4.","aide":"Attention au signe moins devant b.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"Le dénominateur vaut **2** : il est réel, ce qui permet de diviser."},{"cle":{"type":"nombre","valeur":-0.5,"tolerance":0.001},"affichage":"−0,5","explication":"Le quotient vaut (−1 + 5i) / 2 : sa partie réelle est **−0,5**."},{"cle":{"type":"nombre","valeur":2.5,"tolerance":0.001},"affichage":"2,5","explication":"La partie imaginaire est 5 / 2 = **2,5**."},{"cle":{"type":"nombre","valeur":3,"tolerance":0},"affichage":"3","explication":"Les parties réelles sont égales : 3a = 9, donc a = **3**."},{"cle":{"type":"nombre","valeur":-4,"tolerance":0},"affichage":"−4","explication":"Les parties imaginaires sont égales : −b = 4, donc b = **−4**. Ainsi z = 3 − 4i."}]$ex$::jsonb),
  ('60bd8e40-bffc-568b-8e6d-1b2016be63d3'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La racine carrée de −5 + 12i","competence":"resoudre","situation":"Hugo cherche les nombres complexes z = a + ib tels que z² = −5 + 12i. Il traduit l’égalité en trois équations réelles, en utilisant aussi le module.","documents":[{"id":"s","type":"tableau","titre":"Les équations d’Hugo","colonnes":["Équation","Expression"],"lignes":[["Parties réelles","a² − b² = −5"],["Parties imaginaires","2ab = 12"],["Modules : |z|² = |z²|","a² + b² = ?"]],"enteteLignes":true,"source":"z² = (a² − b²) + 2ab i"},{"id":"m","type":"texte","genre":"consigne","titre":"Rappel","blocs":["Le module de −5 + 12i vaut √((−5)² + 12²).","On additionne puis on soustrait les équations pour isoler a² et b²."]}],"questions":[{"enonce":"Quelle est la valeur de a² + b² ? C’est le module de −5 + 12i.","aide":"Calcule 25 + 144, puis la racine carrée.","type":"nombre"},{"enonce":"Quelle est la valeur de a² ? Additionne a² + b² = 13 et a² − b² = −5, puis divise par 2.","aide":"13 + (−5) = 8.","type":"nombre"},{"enonce":"Quelle est la valeur de b² ? Soustrais les deux équations : 13 − (−5), puis divise par 2.","aide":"13 + 5 = 18.","type":"nombre"},{"enonce":"Que dit l’équation 2ab = 12 sur les signes de a et de b ?","aide":"Un produit positif est obtenu avec deux nombres de même signe.","type":"choix","options":[{"id":"a","texte":"Que a et b sont de signes contraires, car le nombre 12 est strictement positif"},{"id":"b","texte":"Que a et b sont tous deux positifs, car leur produit est égal à 12 exactement"},{"id":"c","texte":"Qu’aucune information n’est donnée, car les signes ne se lisent pas dans un produit"},{"id":"d","texte":"Que a et b ont le même signe, car leur produit 2ab est positif"}],"multiple":false},{"enonce":"Parmi les deux solutions, celle dont la partie réelle est positive a pour partie imaginaire…","aide":"a = 2 et b a le même signe que a.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":13,"tolerance":0},"affichage":"13","explication":"√(25 + 144) = √169 = **13**."},{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4","explication":"2a² = 8, donc a² = **4**."},{"cle":{"type":"nombre","valeur":9,"tolerance":0},"affichage":"9","explication":"2b² = 18, donc b² = **9**."},{"cle":{"type":"choix","ids":["d"]},"explication":"2ab = 12 > 0 : a et b ont le **même signe**. Il y a donc deux solutions : (a ; b) = (2 ; 3) et (−2 ; −3)."},{"cle":{"type":"nombre","valeur":3,"tolerance":0},"affichage":"3","explication":"Avec a = 2 et b du même signe, b = **3** : z = 2 + 3i (l’autre solution est −2 − 3i)."}]$ex$::jsonb),
