   $ex${"titre":"Une rotation de centre Ω","competence":"geometrie","situation":"Dans le plan complexe, la rotation r de centre Ω(2) et d’angle π/2 s’écrit z′ − 2 = i(z − 2). Anaïs cherche l’image de A(4 + 2i). Elle étudie ensuite l’homothétie de centre Ω et de rapport 3.","documents":[{"id":"f","type":"figure","cadre":{"xmin":-1,"xmax":5,"ymin":-1,"ymax":4},"quadrillage":true,"axes":true,"points":[{"id":"W","x":2,"y":0,"position":"se","nom":"Ω"},{"id":"A","x":4,"y":2,"position":"ne"},{"id":"A2","x":0,"y":2,"position":"no","nom":"A′"},{"id":"O","x":0,"y":0,"position":"so"}],"segments":[{"de":"W","a":"A"},{"de":"W","a":"A2"}],"source":"Figure écrite pour l’exercice"},{"id":"t","type":"tableau","titre":"Calcul de l’image de A","colonnes":["Étape","Résultat"],"lignes":[["z_A − 2","2 + 2i"],["i × (z_A − 2)","?"],["z_A′ = i(z_A − 2) + 2","?"]],"enteteLignes":true,"source":"z_A = 4 + 2i"}],"questions":[{"enonce":"Quelle est la partie réelle de i(2 + 2i) ? Développe avec i² = −1.","aide":"i × 2 + i × 2i = 2i + 2i².","type":"nombre"},{"enonce":"Quelle est la partie imaginaire de z_A′ = (−2 + 2i) + 2 ?","aide":"Seule la partie réelle change quand on ajoute 2.","type":"nombre"},{"enonce":"Touche l’image A′ de A par la rotation r.","aide":"A′ a pour affixe 2i : abscisse 0, ordonnée 2.","type":"zone","document":"f","multiple":false},{"enonce":"Quelle est la longueur ΩA′, arrondie au centième ? Une rotation conserve ΩA = |2 + 2i|.","aide":"Calcule √(2² + 2²).","type":"nombre"},{"enonce":"L’homothétie de centre Ω et de rapport 3 envoie A sur A″ avec z″ − 2 = 3(2 + 2i). Quelle est la partie réelle de z″ ?","aide":"3 × 2 = 6, puis on ajoute 2.","type":"nombre"}]}$ex$::jsonb,
