   $ex$[{"cle":{"type":"nombre","valeur":702,"tolerance":0},"affichage":"702","explication":"7,02 ÷ 0,01 = **702**, comme dans le tableau."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le numérateur tend vers 7 > 0 et le dénominateur vers 0 par valeurs positives : le quotient tend vers **+∞**."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2","explication":"2x ÷ x = **2**. Le tableau le confirme : 2,072 puis 2,007."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1"}},"explication":"f tend vers ±∞ en 3 : **x = 3 est asymptote verticale**. f tend vers 2 en +∞ : **y = 2 est asymptote horizontale**."}]$ex$::jsonb),
  ('af251c40-2b54-507c-80d7-7c0f8f05b1f3'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Une asymptote oblique","competence":"raisonner","situation":"Soit f(x) = (x² + x + 1) ÷ x = x + 1 + 1 ÷ x pour x > 0. On compare la courbe de f à la droite d : y = x + 1.","documents":[{"id":"ecart","type":"tableau","titre":"Écart entre f(x) et x + 1","colonnes":["x","10","100","1 000"],"lignes":[["f(x)",11.1,101.01,1001.001],["x + 1",11,101,1001],["f(x) − (x + 1)",0.1,"?",0.001]],"enteteLignes":true,"source":"Valeurs exactes"},{"id":"meth","type":"texte","genre":"consigne","titre":"Rappel","blocs":["d : y = ax + b est asymptote oblique si f(x) − (ax + b) tend vers 0 en +∞."]}],"questions":[{"enonce":"Complète la case « ? » : quel est l’écart f(100) − 101 ?","aide":"101,01 − 101.","type":"nombre"},{"enonce":"Quelle est la limite de f(x) ÷ x quand x tend vers +∞ ? (f(x) ÷ x = 1 + 1/x + 1/x².)","aide":"1/x et 1/x² tendent vers 0.","type":"nombre"},{"enonce":"Quelle est l’équation de l’asymptote oblique de la courbe en +∞ ?","aide":"f(x) − (x + 1) = 1/x tend vers 0.","type":"choix","options":[{"id":"a","texte":"y = x + 1"},{"id":"b","texte":"y = 1"},{"id":"c","texte":"y = x + 2"},{"id":"d","texte":"y = x"}],"multiple":false},{"enonce":"Pour x > 0, la courbe est-elle au-dessus ou au-dessous de cette asymptote ?","aide":"Regarde le signe de f(x) − (x + 1).","type":"choix","options":[{"id":"a","texte":"Elle la coupe en x = 1, puisque c’est là que 1/x atteint la valeur 1"},{"id":"b","texte":"Au-dessus, car pour x > 0 la différence f(x) − (x + 1) = 1/x est positive"},{"id":"c","texte":"Au-dessous, car la différence 1/x est très petite et tend vers 0 quand x grandit"},{"id":"d","texte":"Elle est confondue avec elle, puisque 1/x tend vers 0 quand x grandit"}],"multiple":false},{"enonce":"Que vaut la limite de f(x) quand x tend vers 0 par valeurs positives ?","aide":"Le terme 1/x devient énorme et positif.","type":"choix","options":[{"id":"a","texte":"Zéro"},{"id":"b","texte":"Un"},{"id":"c","texte":"Moins l’infini"},{"id":"d","texte":"Plus l’infini"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":0.01,"tolerance":0},"affichage":"0,01","explication":"101,01 − 101 = **0,01**. L’écart vaut 1 ÷ x."},{"cle":{"type":"nombre","valeur":1,"tolerance":0},"affichage":"1","explication":"f(x) ÷ x tend vers **1** : le coefficient directeur de l’asymptote est 1."},{"cle":{"type":"choix","ids":["a"]},"explication":"f(x) − (x + 1) = 1/x tend vers 0 : l’asymptote est **y = x + 1**."},{"cle":{"type":"choix","ids":["b"]},"explication":"f(x) − (x + 1) = 1/x > 0 pour x > 0 : la courbe est **au-dessus** de l’asymptote."},{"cle":{"type":"choix","ids":["d"]},"explication":"Quand x tend vers 0⁺, 1/x tend vers +∞ et le reste vers 1 : f tend vers **+∞**. La droite x = 0 est asymptote verticale."}]$ex$::jsonb),
  ('0f922e32-65ad-534e-ae45-353336ec22f6'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Reconnaître u et u′","competence":"calculer","situation":"Pour dériver une composée, on repère d’abord la fonction intérieure u, puis on calcule u′. Le tableau donne quatre fonctions avec leur u et leur u′.","documents":[{"id":"u","type":"tableau","titre":"Fonctions, u et u′","colonnes":["Fonction","u(x)","u′(x)"],"lignes":[["e^(3x)","3x","3"],["ln(2x + 1)","2x + 1","2"],["(x² + 1)³","x² + 1","2x"],["√(x + 1)","x + 1","1"]],"enteteLignes":true}],"questions":[{"enonce":"Associe chaque fonction à sa dérivée.","aide":"Formules : (e^u)′ = u′ e^u ; (ln u)′ = u′/u ; (uⁿ)′ = n u′ uⁿ⁻¹ ; (√u)′ = u′/(2√u).","type":"association","gauche":[{"id":"g0","texte":"Exponentielle de 3x"},{"id":"g1","texte":"Logarithme de 2x + 1"},{"id":"g2","texte":"Cube de x² + 1"},{"id":"g3","texte":"Racine de x + 1"}],"droite":[{"id":"d0","texte":"1 / (2√(x + 1))"},{"id":"d1","texte":"2 / (2x + 1)"},{"id":"d2","texte":"6x (x² + 1)²"},{"id":"d3","texte":"3 e^(3x)"}]},{"enonce":"Soit f(x) = e^(2x + 1). Calcule f′(0), arrondi au centième.","aide":"f′(x) = 2 e^(2x + 1) ; e ≈ 2,718.","type":"nombre"},{"enonce":"Élise écrit (e^(3x))′ = e^(3x). Quelle est son erreur ?","aide":"Dérivée d’une composée : on multiplie par la dérivée de l’intérieur.","type":"choix","options":[{"id":"a","texte":"Elle oublie de prendre le logarithme"},{"id":"b","texte":"Elle oublie de multiplier par u′ = 3"},{"id":"c","texte":"Il n’y a pas d’erreur"},{"id":"d","texte":"Elle dérive la mauvaise fonction extérieure"}],"multiple":false},{"enonce":"Soit h(x) = (x² + 1)³. Calcule h′(1).","aide":"h′(x) = 6x (x² + 1)².","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g3":"d0","g1":"d1","g2":"d2","g0":"d3"}},"explication":"On applique u′ e^u, u′/u, n u′ uⁿ⁻¹ et u′/(2√u) avec les u et u′ du tableau."},{"cle":{"type":"nombre","valeur":5.44,"tolerance":0.01},"affichage":"5,44","explication":"f′(0) = 2 e ≈ **5,44**."},{"cle":{"type":"choix","ids":["b"]},"explication":"La dérivée de e^u est u′ e^u. Ici u′ = 3 : (e^(3x))′ = **3 e^(3x)**."},{"cle":{"type":"nombre","valeur":24,"tolerance":0},"affichage":"24","explication":"h′(1) = 6 × 1 × 2² = **24**."}]$ex$::jsonb),
