   $ex${"titre":"Les calculs de Yanis","competence":"calculer","situation":"Yanis veut exprimer des logarithmes avec seulement ln 2 et ln 3. Il a recopié trois règles dans son carnet.","documents":[{"id":"val","type":"tableau","titre":"Les deux valeurs connues","colonnes":["Nombre","Valeur approchée"],"lignes":[["ln 2",0.693],["ln 3",1.099]],"enteteLignes":true,"source":"Valeurs arrondies au millième"},{"id":"r","type":"texte","genre":"consigne","titre":"Le carnet de Yanis","blocs":["ln(a × b) = ln a + ln b","ln(a ÷ b) = ln a − ln b","ln(aⁿ) = n × ln a"]}],"questions":[{"enonce":"Relie chaque logarithme à son écriture avec ln 2 et ln 3.","aide":"Décompose : 6 = 2 × 3 ; 8 = 2³ ; 3/2 est un quotient ; 1/4 = 2⁻².","type":"association","gauche":[{"id":"g0","texte":"ln 6"},{"id":"g1","texte":"ln 8"},{"id":"g2","texte":"ln(3/2)"},{"id":"g3","texte":"ln(1/4)"}],"droite":[{"id":"d0","texte":"ln 3 moins ln 2"},{"id":"d1","texte":"trois fois ln 2"},{"id":"d2","texte":"ln 2 plus ln 3"},{"id":"d3","texte":"deux fois l’opposé de ln 2"}]},{"enonce":"Calcule ln 6 = ln 2 + ln 3, arrondi au millième.","aide":"Additionne les deux valeurs du tableau.","type":"nombre"},{"enonce":"Calcule ln 18 = ln 2 + 2 ln 3, arrondi au centième.","aide":"Double d’abord ln 3.","type":"nombre"},{"enonce":"Trie ces égalités : lesquelles sont vraies pour tous les réels a et b strictement positifs ?","aide":"Le logarithme transforme un produit en somme, rien d’autre : une somme dans ln ne se découpe pas.","type":"categories","categories":[{"id":"c0","texte":"Vraie"},{"id":"c1","texte":"Fausse"}],"items":[{"id":"i0","texte":"ln(a³) = 3 ln a"},{"id":"i1","texte":"ln(1/b) = −ln b"},{"id":"i2","texte":"ln(a + b) = ln a + ln b"},{"id":"i3","texte":"ln(ab) = ln a + ln b"},{"id":"i4","texte":"ln a × ln b = ln(ab)"},{"id":"i5","texte":"ln(a²) = 2 + ln a"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2","g3":"d3"}},"explication":"**ln 6 = ln 2 + ln 3** ; **ln 8 = 3 ln 2** ; **ln(3/2) = ln 3 − ln 2** ; **ln(1/4) = −2 ln 2**."},{"cle":{"type":"nombre","valeur":1.792,"tolerance":0.002},"affichage":"1,792","explication":"0,693 + 1,099 = **1,792**."},{"cle":{"type":"nombre","valeur":2.89,"tolerance":0.01},"affichage":"2,89","explication":"ln 18 = 0,693 + 2 × 1,099 = 0,693 + 2,198 = **2,89**."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c0","i4":"c1","i5":"c1"}},"explication":"Les règles du carnet sont vraies (et ln(1/b) = −ln b en découle). **ln(a + b), ln(a − b) et le produit de logarithmes ne se simplifient pas ainsi.**"}]$ex$::jsonb),
  ('f62292b9-7a62-50db-bb01-ac81b5857c68'::uuid, 3, 3, 15, 50, 6,
   $ex${"titre":"Doubler son capital","competence":"modeliser","situation":"Léa place 2 000 € à 3 % d’intérêts par an, sans jamais retirer d’argent. Son capital après n années est C(n) = 2 000 × 1,03ⁿ. Elle veut savoir quand il aura doublé, puis triplé.","documents":[{"id":"cap","type":"tableau","titre":"Le capital de Léa","colonnes":["Années n","0","10","20","24"],"lignes":[["C(n) en €","2 000","2 687,83","3 612,22","?"]],"enteteLignes":true,"source":"Valeurs arrondies au centime"},{"id":"e","type":"texte","genre":"consigne","titre":"Le point de méthode","blocs":["Pour résoudre 1,03ⁿ ≥ 2, on compose par ln, qui est strictement croissante : n × ln 1,03 ≥ ln 2.","ln 2 ≈ 0,6931 ; ln 3 ≈ 1,0986."]}],"questions":[{"enonce":"Calcule ln 1,03, arrondi à 10⁻⁴ (à la calculatrice).","aide":"Utilise la touche ln.","type":"nombre"},{"enonce":"Pourquoi peut-on écrire n × ln 1,03 ≥ ln 2 à partir de 1,03ⁿ ≥ 2 ?","aide":"Deux propriétés : le sens des inégalités, et la règle sur les puissances.","type":"choix","options":[{"id":"a","texte":"ln est strictement croissante et ln(1,03ⁿ) = n ln 1,03"},{"id":"b","texte":"Parce que ln est décroissante"},{"id":"c","texte":"Parce que 1,03 est plus grand que 1, sans autre raison"},{"id":"d","texte":"Parce que ln(1,03ⁿ) = ln n × ln 1,03"}],"multiple":false},{"enonce":"Au bout de combien d’années entières le capital a-t-il doublé pour la première fois ? (n ≥ ln 2 ÷ ln 1,03 ≈ 23,4)","aide":"n doit être un entier supérieur ou égal à 23,4.","type":"nombre"},{"enonce":"Calcule C(24), arrondi à l’euro. (C(24) = 2 000 × 1,03²⁴)","aide":"Utilise la touche puissance de la calculatrice.","type":"nombre","unite":"€"},{"enonce":"Au bout de combien d’années entières le capital a-t-il triplé pour la première fois ? (n ≥ ln 3 ÷ ln 1,03)","aide":"Calcule 1,0986 ÷ 0,0296, puis prends l’entier supérieur.","type":"nombre"},{"enonce":"La suite ln(C(n)) est arithmétique. Quelle est sa raison, arrondie à 10⁻⁴ ?","aide":"ln(C(n)) = ln 2 000 + n ln 1,03.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":0.0296,"tolerance":0.0001},"affichage":"0,0296","explication":"ln 1,03 ≈ **0,0296**."},{"cle":{"type":"choix","ids":["a"]},"explication":"ln est croissante : elle conserve l’inégalité ; et ln(1,03ⁿ) = n ln 1,03. On obtient **n ln 1,03 ≥ ln 2**."},{"cle":{"type":"nombre","valeur":24,"tolerance":0},"affichage":"24","explication":"n ≥ 23,4 donc le premier entier est **24**. Contrôle : 1,03²³ ≈ 1,97 < 2 et 1,03²⁴ ≈ 2,03 > 2."},{"cle":{"type":"nombre","valeur":4066,"tolerance":1},"affichage":"4066 €","explication":"1,03²⁴ ≈ 2,0328, donc C(24) ≈ 4 065,6 €, soit **4 066 €** à l’euro près."},{"cle":{"type":"nombre","valeur":38,"tolerance":0},"affichage":"38","explication":"n ≥ ln 3 ÷ ln 1,03 ≈ 37,2 : le premier entier est **38**."},{"cle":{"type":"nombre","valeur":0.0296,"tolerance":0.0001},"affichage":"0,0296","explication":"ln(C(n+1)) − ln(C(n)) = ln 1,03 ≈ **0,0296** : la raison est constante."}]$ex$::jsonb),
