  ('bec4cd4e-b6b2-5600-9635-1d5da3a5f6ea'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Qui gagne : eπ ou πe ?","competence":"raisonner","situation":"Soit g(x) = ln x ÷ x sur ]0 ; +∞[. Tiphaine veut comparer les deux nombres e^π et π^e sans calculatrice. Elle commence par étudier g.","documents":[{"id":"val","type":"tableau","titre":"Quelques valeurs de g","colonnes":["x","1","2","e","4","10","100"],"lignes":[["g(x)",0,0.347,0.368,0.347,0.23,0.046]],"enteteLignes":true,"source":"Valeurs arrondies au millième"},{"id":"der","type":"texte","genre":"consigne","titre":"La dérivée","blocs":["g′(x) = (1 − ln x) ÷ x².","g′(x) > 0 pour x < e et g′(x) < 0 pour x > e."]}],"questions":[{"enonce":"Touche la valeur la plus grande prise par g dans ce tableau.","aide":"Compare les valeurs de la ligne de g.","type":"zone","document":"val","multiple":false},{"enonce":"Calcule g′(1) avec g′(x) = (1 − ln x) ÷ x².","aide":"ln 1 = 0.","type":"nombre"},{"enonce":"Combien de solutions l’équation g(x) = 0,3 admet-elle ?","aide":"g croît jusqu’à 0,368 puis décroît vers 0 : 0,3 est entre 0 et le maximum des deux côtés.","type":"nombre"},{"enonce":"Puisque π > e et que g décroît sur [e ; +∞[, que peut-on dire de g(π) et g(e) ?","aide":"g est strictement décroissante sur [e ; +∞[.","type":"choix","options":[{"id":"a","texte":"On ne peut rien dire de g(π)"},{"id":"b","texte":"g(π) est plus petit que g(e)"},{"id":"c","texte":"g(π) est plus grand que g(e)"},{"id":"d","texte":"g(π) est égal à g(e), car g est constante après e"}],"multiple":false},{"enonce":"En multipliant par eπ, que donne ln π ÷ π < 1/e ?","aide":"Multiplie les deux membres par eπ > 0, puis compose par l’exponentielle.","type":"choix","options":[{"id":"a","texte":"e ln π est supérieur à π : donc π^e est supérieur à e^π"},{"id":"b","texte":"π ln e est inférieur à e ln π : donc e^π est inférieur à π^e"},{"id":"c","texte":"ln π est inférieur à ln e : donc π est inférieur à e"},{"id":"d","texte":"e ln π est inférieur à π : donc π^e est inférieur à e^π"}],"multiple":false}]}$ex$::jsonb,
