   $ex${"titre":"Deux machines en série","competence":"raisonner","situation":"Dans une usine, une pièce passe d’abord par la machine A, puis par la machine B. Les durées X et Y (en minutes) sont indépendantes. La durée totale est T = X + Y. Léo prétend que σ(T) = 3 + 4 = 7.","documents":[{"id":"mac","type":"tableau","titre":"Les deux machines","colonnes":["Machine","Espérance","Écart-type"],"lignes":[["A (durée X)",12,3],["B (durée Y)",8,4]],"enteteLignes":true,"source":"Données imaginées pour l’exercice ; durées en minutes"}],"questions":[{"enonce":"Calcule E(T) = E(X) + E(Y), en minutes.","aide":"L’espérance est toujours additive.","type":"nombre"},{"enonce":"Calcule la variance V(T) = V(X) + V(Y) (X et Y sont indépendantes). Commence par les variances : 3² et 4².","aide":"V(X) = 9 et V(Y) = 16.","type":"nombre"},{"enonce":"Calcule l’écart-type σ(T) = √V(T), en minutes.","aide":"√25.","type":"nombre"},{"enonce":"Pourquoi le raisonnement de Léo (3 + 4 = 7) est-il faux ?","aide":"Quelle grandeur est additive sous indépendance ?","type":"choix","options":[{"id":"a","texte":"Parce que l’écart-type d’une somme est la moyenne des écarts-types"},{"id":"b","texte":"Parce que X et Y ne sont pas indépendantes"},{"id":"c","texte":"Parce que 3 + 4 n’est pas 7"},{"id":"d","texte":"Les écarts-types ne s’additionnent pas : ce sont les variances"}],"multiple":false},{"enonce":"Calcule V(X − Y) : attention, la variance d’une différence de variables indépendantes s’additionne aussi.","aide":"V(−Y) = (−1)² V(Y) = V(Y).","type":"nombre"}]}$ex$::jsonb,
